class HTMLContextParser:
    """
    Stack-based HTML parser for XSS context tracking.
    
    Tracks the current context (HTML_TEXT, SCRIPT_STRING, CSS_BLOCK, HTML_ATTRIBUTE)
    to determine if a reflected payload is actually exploitable.
    """
    
    HTML_TEXT = 'HTML_TEXT'
    SCRIPT_STRING = 'SCRIPT_STRING'
    CSS_BLOCK = 'CSS_BLOCK'
    HTML_ATTRIBUTE = 'HTML_ATTRIBUTE'
    
    def __init__(self):
        self.context_stack = [self.HTML_TEXT]
        self.current_tag = None
        self.current_attribute = None
        self.in_script = False
        self.in_style = False
        self.string_delimiter = None  # '"', "'", or None
    
    def parse(self, html: str, payload: str) -> dict:
        """
        Parse HTML and determine the context where payload appears.
        
        Returns:
            dict: {
                'context': str,  # One of the context constants
                'tag': str,      # Current HTML tag if in attribute
                'attribute': str, # Current attribute name if in attribute
                'is_safe': bool, # True if context is Self-XSS / safe
                'payload_mutated': str  # Mutated payload if needed
            }
        """
        self.context_stack = [self.HTML_TEXT]
        self.current_tag = None
        self.current_attribute = None
        self.in_script = False
        self.in_style = False
        self.string_delimiter = None
        
        i = 0
        payload_index = html.lower().find(payload.lower())
        
        while i < len(html):
            # Check if we've reached the payload location
            if payload_index != -1 and i >= payload_index:
                # Determine context at this position
                context = self._get_current_context()
                return self._analyze_context(context, payload)
            
            # Parse HTML character by character
            char = html[i]
            
            # Handle tag opening
            if char == '<' and i + 1 < len(html):
                next_char = html[i + 1]
                if next_char == '/':
                    # Closing tag
                    self._handle_closing_tag(html, i)
                    # Skip to after '>'
                    while i < len(html) and html[i] != '>':
                        i += 1
                elif next_char == '!' or next_char == '?':
                    # Comment or doctype - skip
                    while i < len(html) and html[i] != '>':
                        i += 1
                else:
                    # Opening tag
                    self._handle_opening_tag(html, i)
                    # Skip to after '>'
                    while i < len(html) and html[i] != '>':
                        i += 1
            elif char == '"' or char == "'":
                # Handle string delimiters
                self._handle_string_delimiter(char)
            elif char == '>':
                # Tag closing
                if self.current_attribute:
                    self.current_attribute = None
            elif char == '<' and i + 1 < len(html) and html[i+1] == '/':
                # Already handled above
                pass
            
            i += 1
        
        # If payload not found or reached end
        context = self._get_current_context()
        return self._analyze_context(context, payload)
    
    def _handle_opening_tag(self, html: str, start_pos: int):
        """Handle opening tag - update context stack."""
        # Extract tag name
        i = start_pos + 1
        tag_name = ''
        while i < len(html) and not html[i].isspace() and html[i] != '>':
            tag_name += html[i]
            i += 1
        
        tag_name = tag_name.lower()
        self.current_tag = tag_name
        
        # Push appropriate context
        if tag_name == 'script':
            self.context_stack.append(self.SCRIPT_STRING)
            self.in_script = True
        elif tag_name == 'style':
            self.context_stack.append(self.CSS_BLOCK)
            self.in_style = True
        else:
            self.context_stack.append(self.HTML_ATTRIBUTE)
    
    def _handle_closing_tag(self, html: str, start_pos: int):
        """Handle closing tag - pop from context stack."""
        # Extract tag name
        i = start_pos + 2  # Skip '</'
        tag_name = ''
        while i < len(html) and not html[i].isspace() and html[i] != '>':
            tag_name += html[i]
            i += 1
        
        tag_name = tag_name.lower()
        
        if tag_name == 'script' and self.in_script:
            self.in_script = False
            if self.context_stack and self.context_stack[-1] == self.SCRIPT_STRING:
                self.context_stack.pop()
        elif tag_name == 'style' and self.in_style:
            self.in_style = False
            if self.context_stack and self.context_stack[-1] == self.CSS_BLOCK:
                self.context_stack.pop()
        elif len(self.context_stack) > 1:
            self.context_stack.pop()
        
        self.current_tag = None
        self.current_attribute = None
        self.string_delimiter = None
    
    def _handle_string_delimiter(self, delimiter: str):
        """Handle string delimiter in JavaScript or attributes."""
        if self.string_delimiter == delimiter:
            # Closing delimiter
            self.string_delimiter = None
        elif self.string_delimiter is None:
            # Opening delimiter
            self.string_delimiter = delimiter
    
    def _get_current_context(self) -> str:
        """Get current context from stack."""
        if not self.context_stack:
            return self.HTML_TEXT
        return self.context_stack[-1]
    
    def _analyze_context(self, context: str, payload: str) -> dict:
        """Analyze context and determine if XSS is exploitable."""
        result = {
            'context': context,
            'tag': self.current_tag,
            'attribute': self.current_attribute,
            'is_safe': False,
            'payload_mutated': payload
        }
        
        # HTML_TEXT context - generally exploitable
        if context == self.HTML_TEXT:
            result['is_safe'] = False
        
        # HTML_ATTRIBUTE context - check if dangerous
        elif context == self.HTML_ATTRIBUTE:
            # Check if attribute is an event handler
            dangerous_attributes = [
                'onload', 'onerror', 'onclick', 'onmouseover', 'onmouseout',
                'onfocus', 'onblur', 'onkeydown', 'onkeyup', 'onsubmit',
                'ondblclick', 'onmousedown', 'onmouseup', 'onmousemove',
                'onmouseenter', 'onmouseleave', 'ontouchstart', 'ontouchend',
                'onchange', 'oninput', 'onreset', 'onselect', 'oninvalid',
                'onanimationend', 'onanimationstart', 'ontransitionend',
                'onmessage', 'onerror', 'onload', 'onresize', 'onscroll',
                'onabort', 'oncanplay', 'oncanplaythrough', 'ondurationchange',
                'onemptied', 'onended', 'onloadeddata', 'onloadedmetadata',
                'onpause', 'onplay', 'onplaying', 'onprogress', 'onratechange',
                'onseeked', 'onseeking', 'onstalled', 'onsuspend', 'ontimeupdate',
                'onvolumechange', 'onwaiting', 'onwheel', 'oncopy', 'oncut',
                'onpaste', 'oncontextmenu', 'ondrag', 'ondragend', 'ondragenter',
                'ondragleave', 'ondragover', 'ondragstart', 'ondrop', 'onafterprint',
                'onbeforeprint', 'onbeforeunload', 'onhashchange', 'onmessage',
                'onoffline', 'ononline', 'onpagehide', 'onpageshow', 'onpopstate',
                'onstorage', 'onunload'
            ]
            
            if self.current_attribute and self.current_attribute.lower() in dangerous_attributes:
                result['is_safe'] = False
            else:
                # Regular attribute like value="", href="", class="" - Self-XSS
                result['is_safe'] = True
        
        # SCRIPT_STRING context - mutate payload to break out
        elif context == self.SCRIPT_STRING:
            if self.string_delimiter == "'":
                result['payload_mutated'] = f"'-alert(1)-'"
            elif self.string_delimiter == '"':
                result['payload_mutated'] = f'"-alert(1)-"'
            else:
                result['payload_mutated'] = payload
            result['is_safe'] = False
        
        # CSS_BLOCK context - generally not exploitable for XSS
        elif context == self.CSS_BLOCK:
            result['is_safe'] = True
        
        return result


def detect_sqli_error_ast(html: str) -> bool:
    """
    Grammar-based SQLi error detector using specific database error codes
    in exact structural contexts instead of keyword frequency counting.
    """
    import re
    
    # Database-specific error code patterns with structural context
    db_error_patterns = [
        # MySQL error codes with context
        r'ORA-\d{5}:\s*\d+:\s*\d+:\s*',  # Oracle: ORA-00001: unique constraint violated
        r'ORA-\d{5}[^a-zA-Z0-9]',        # Oracle: ORA- followed by non-alphanumeric
        r'PLS-\d{5}[^a-zA-Z0-9]',        # Oracle PL/SQL errors
        r'MySQL.*error\s+\d{4}',          # MySQL explicit error messages
        r'MySQL.*syntax\s+error',         # MySQL syntax errors
        r'You have an error in your SQL syntax',  # MySQL classic error
        r'\b1064\b.*MySQL',               # MySQL error 1064 with database name
        r'\b1065\b.*MySQL',               # MySQL error 1065 with database name
        r'\b1146\b.*MySQL',               # MySQL error 1146 with database name
        
        # PostgreSQL error codes with SQLSTATE
        r'SQLSTATE\[\d{5}\]',            # PostgreSQL SQLSTATE codes
        r'ERROR:\s*\d{5}:\s*',           # PostgreSQL structured errors
        r'ERROR:\s*syntax\s+error\s+(at|near)',  # PostgreSQL syntax errors
        r'PG::.*Error',                  # Rails PostgreSQL errors
        r'PostgreSQL.*ERROR:\s*\d{5}',   # PostgreSQL numbered errors
        
        # SQLite error patterns
        r'SQLite error:\s*\d+:\s*',      # SQLite numbered errors
        r'sqlite3.OperationalError:\s*', # Python SQLite errors
        r'SQLiteException:\s*\d+',       # Java SQLite errors
        r'near\s+["\'].*["\']:\s*syntax\s+error',  # SQLite syntax error with context
        
        # SQL Server patterns
        r'\[Microsoft\]\[ODBC\s+SQL\s+Server\]',  # SQL Server ODBC errors
        r'SQLServer.*Exception:\s*\d+',           # .NET SQL Server errors
        r'Message:\s*\d+, Level \d+, State \d+',  # SQL Server structured messages
        r'Incorrect syntax near\s+[\'"]',         # SQL Server syntax errors
        r'Violation of PRIMARY KEY constraint',  # SQL Server constraint errors
        
        # Generic database error patterns with structural context
        r'SQL\s+syntax.*MySQL',             # SQL syntax with database name
        r'ORA-\d{5}',                       # Oracle errors (catch-all)
        r'SQLSTATE\s*\d{5}',                # SQLSTATE codes
        r'DatabaseError:\s*\d+',            # Generic database errors
        r'SQLException:\s*\d+',             # Java SQL exceptions
    ]
    
    # Contextual patterns that indicate SQLi (require error codes nearby)
    contextual_indicators = [
        r'near\s+[\'"]\s*[\w\s]+\s*[\'"]\s+at line \d+',  # MySQL-style location
        r'at line \d+[^a-zA-Z0-9]',                        # Line number context
        r'in your SQL syntax[^a-zA-Z0-9]',                 # Syntax error context
        r'syntax error.*near[^a-zA-Z0-9]',                 # Generic syntax context
        r'quoted string not properly terminated[^a-zA-Z0-9]',  # Quote context
        r'unterminated string[^a-zA-Z0-9]',                # String termination
    ]
    
    html_lower = html.lower()
    
    # Check for database-specific error codes first (highest confidence)
    for pattern in db_error_patterns:
        if re.search(pattern, html, re.IGNORECASE):
            return True
    
    # Check for contextual patterns (medium confidence)
    for pattern in contextual_indicators:
        if re.search(pattern, html, re.IGNORECASE):
            # Additional check: ensure there's some database-related term nearby
            if re.search(r'(sql|mysql|postgres|oracle|sqlite|database|query)', html_lower):
                return True
    
    return False

def validate_sqli_error_message(error_message: str) -> dict:
    """
    SQL Dialect Grammar Validation: Parse and validate SQL error messages.
    
    Returns confidence based on error message patterns:
    - SQLSTATE[42000] (PDO error): Always true positive (confidence 1.0)
    - Generic "SQL" in 500 error without line number: Downgrade to 0 (FP)
    - Database-specific error codes: High confidence
    - Contextual indicators with database terms: Medium confidence
    
    Args:
        error_message: The error message to validate
        
    Returns:
        dict: {
            'is_valid_sqli': bool,
            'confidence': float,  # 0.0 to 1.0
            'database_type': str,  # mysql, postgresql, sqlite, oracle, sqlserver, unknown
            'error_code': str,  # Extracted error code if available
            'reason': str  # Explanation of the validation result
        }
    """
    import re
    
    result = {
        'is_valid_sqli': False,
        'confidence': 0.0,
        'database_type': 'unknown',
        'error_code': None,
        'reason': ''
    }
    
    if not error_message:
        result['reason'] = 'Empty error message'
        return result
    
    error_lower = error_message.lower()
    
    # Check for PDO SQLSTATE[42000] - always true positive
    pdo_match = re.search(r'SQLSTATE\[(\d{5})\]', error_message, re.IGNORECASE)
    if pdo_match:
        error_code = pdo_match.group(1)
        result['error_code'] = error_code
        result['database_type'] = 'pdo'
        
        # SQLSTATE class 42 = syntax error or access rule violation
        if error_code.startswith('42'):
            result['is_valid_sqli'] = True
            result['confidence'] = 1.0
            result['reason'] = f'PDO SQLSTATE[{error_code}] - syntax error, always true positive'
            return result
        else:
            result['is_valid_sqli'] = True
            result['confidence'] = 0.9
            result['reason'] = f'PDO SQLSTATE[{error_code}] - database error detected'
            return result
    
    # Check for database-specific error codes
    database_patterns = {
        'mysql': [
            (r'\b1064\b', 'syntax error'),
            (r'\b1065\b', 'invalid query'),
            (r'\b1146\b', 'table not found'),
            (r"You have an error in your SQL syntax", 'syntax error'),
            (r'MySQL.*syntax\s+error', 'syntax error'),
        ],
        'postgresql': [
            (r'ERROR:\s*42\d{3}', 'syntax error'),
            (r'SQLSTATE\s+42\d{3}', 'syntax error'),
            (r'PG::.*Error', 'database error'),
            (r'PostgreSQL.*ERROR:\s*\d{5}', 'structured error'),
        ],
        'sqlite': [
            (r'SQLite error:\s*\d+:\s*', 'numbered error'),
            (r'sqlite3\.OperationalError:\s*', 'python error'),
            (r'SQLiteException:\s*\d+', 'java error'),
        ],
        'oracle': [
            (r'ORA-\d{5}', 'oracle error'),
            (r'PLS-\d{5}', 'pl/sql error'),
        ],
        'sqlserver': [
            (r'\[Microsoft\]\[ODBC\s+SQL\s+Server\]', 'odbc error'),
            (r'SQLServer.*Exception:\s*\d+', '.net error'),
            (r'Message:\s*\d+, Level \d+, State \d+', 'structured message'),
        ]
    }
    
    for db_type, patterns in database_patterns.items():
        for pattern, description in patterns:
            if re.search(pattern, error_message, re.IGNORECASE):
                result['database_type'] = db_type
                result['is_valid_sqli'] = True
                result['confidence'] = 0.85
                result['reason'] = f'{db_type.upper()} {description} detected'
                
                # Extract error code if available
                code_match = re.search(r'\b(\d{4,5})\b', error_message)
                if code_match:
                    result['error_code'] = code_match.group(1)
                
                return result
    
    # Check for generic "SQL" mention in 500 error without specific indicators
    if re.search(r'500\s+internal\s+server\s+error', error_lower, re.IGNORECASE):
        if 'sql' in error_lower:
            # Check if there are specific indicators (line numbers, error codes)
            has_line_number = re.search(r'line\s+\d+', error_lower)
            has_error_code = re.search(r'error\s+\d+', error_lower)
            has_syntax_error = re.search(r'syntax\s+error', error_lower)
            
            if not (has_line_number or has_error_code or has_syntax_error):
                # Generic SQL mention in 500 error - likely false positive
                result['is_valid_sqli'] = False
                result['confidence'] = 0.0
                result['reason'] = 'Generic SQL mention in 500 error without specific indicators - likely false positive'
                return result
    
    # Check for contextual indicators with database terms
    contextual_patterns = [
        r'syntax\s+error.*near',
        r'unclosed\s+quotation',
        r'unterminated\s+string',
        r'incorrect\s+syntax',
    ]
    
    for pattern in contextual_patterns:
        if re.search(pattern, error_lower):
            # Ensure database term is present
            if re.search(r'(sql|mysql|postgres|oracle|sqlite|database|query)', error_lower):
                result['is_valid_sqli'] = True
                result['confidence'] = 0.6
                result['reason'] = 'Contextual SQL syntax error with database term'
                return result
    
    # No valid SQLi indicators found
    result['reason'] = 'No valid SQLi error patterns detected'
    return result

def normalize_dynamic_tokens(text: str) -> str:
    """
    Differential Response Analyzer: Removes dynamic tokens before comparing lengths.
    Ignores CSRF tokens, timestamps, session IDs, UUIDs, and other dynamic elements.
    """
    import re
    
    if not text:
        return text
    
    # Patterns for dynamic tokens to normalize
    dynamic_patterns = [
        # CSRF tokens and nonces
        r'csrf[_-]?token["\']?\s*[:=]\s*["\'][a-zA-Z0-9/_-]{20,}["\']',
        r'nonce["\']?\s*[:=]\s*["\'][a-zA-Z0-9/_-]{20,}["\']',
        r'_token["\']?\s*[:=]\s*["\'][a-zA-Z0-9/_-]{20,}["\']',
        r'authenticity_token["\']?\s*[:=]\s*["\'][a-zA-Z0-9/_-]{20,}["\']',
        
        # Timestamps (Unix timestamps, ISO dates, etc.)
        r'\b\d{10,13}\b',  # Unix timestamps (10 or 13 digits)
        r'\d{4}-\d{2}-\d{2}[T\s]\d{2}:\d{2}:\d{2}',  # ISO 8601 dates
        r'\d{2}/\d{2}/\d{4}\s+\d{2}:\d{2}:\d{2}',  # US date format
        
        # UUIDs and GUIDs
        r'[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}',
        r'\{[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\}',
        
        # Session IDs and random strings
        r'session[_-]?id["\']?\s*[:=]\s*["\'][a-zA-Z0-9]{20,}["\']',
        r'PHPSESSID["\']?\s*[:=]\s*["\'][a-zA-Z0-9]{20,}["\']',
        r'JSESSIONID["\']?\s*[:=]\s*["\'][a-zA-Z0-9]{20,}["\']',
        r'ASP\.NET_SessionId["\']?\s*[:=]\s*["\'][a-zA-Z0-9]{20,}["\']',
        
        # Request/Trace IDs
        r'request[_-]?id["\']?\s*[:=]\s*["\'][a-zA-Z0-9/_-]{20,}["\']',
        r'trace[_-]?id["\']?\s*[:=]\s*["\'][a-zA-Z0-9/_-]{20,}["\']',
        r'correlation[_-]?id["\']?\s*[:=]\s*["\'][a-zA-Z0-9/_-]{20,}["\']',
        
        # JWT tokens
        r'eyJ[a-zA-Z0-9_-]+\.[a-zA-Z0-9_-]+\.[a-zA-Z0-9_-]+',
        
        # Generic random hex/base64 strings (longer than 16 chars)
        r'["\'][a-zA-Z0-9/_-]{32,}["\']',
        
        # Cache busting parameters
        r'\?v=\d+',
        r'&v=\d+',
        r'\?_=\d+',
        r'&_=\d+',
    ]
    
    normalized = text
    for pattern in dynamic_patterns:
        normalized = re.sub(pattern, '[DYNAMIC]', normalized, flags=re.IGNORECASE)
    
    return normalized

PASSWD_PATTERN = re.compile(r"root:x:0:0|daemon:x:1:1|root:.*:0:", re.I)
COMMAND_PATTERN = re.compile(r"uid=\d+|gid=\d+|groups=|Volume Serial Number|Directory of ", re.I)
AWS_META_PATTERN = re.compile(r"(ami-id|instance-id|public-keys|security-credentials)", re.I)

_obfuscation_cache = {}

def obfuscate(payload, context="param"):
    """
    Context-aware payload obfuscation for different injection contexts.
    
    Contexts:
    - param: URL parameter injection (default)
    - json: JSON body injection
    - html: HTML injection (innerHTML, etc.)
    - js: JavaScript code injection
    - url: URL fragment/path injection
    - css: CSS injection
    - sql: SQL injection context
    """
    cache_key = (payload, context)
    if cache_key in _obfuscation_cache:
        return _obfuscation_cache[cache_key]
    
    def generate_variants():
        yield payload
        
        # Context-specific escaping
        if context == "json":
            # JSON-in-HTML context: Handle JSON encoding and HTML entity encoding
            yield json_escape(payload)
            yield json_unicode_escape(payload)
            yield json_html_escape(payload)
            # JSON property name obfuscation
            if "=" in payload or ":" in payload:
                obfuscated = json_property_obfuscation(payload)
                if obfuscated != payload:
                    yield obfuscated
                
        elif context == "html":
            # HTML injection context: Handle entity encoding and script tags
            yield html_entity_encode(payload)
            yield html_hex_encode(payload)
            yield html_decimal_encode(payload)
            # Script tag obfuscation
            if "<script" in payload.lower() or "alert(" in payload.lower():
                yield script_tag_obfuscation(payload)
                
        elif context == "js":
            # JavaScript injection context: Handle string escaping and code obfuscation
            yield js_string_escape(payload)
            yield js_unicode_escape(payload)
            yield js_backtick_escape(payload)
            # JavaScript code obfuscation
            if "alert(" in payload.lower() or "document." in payload.lower():
                yield js_code_obfuscation(payload)
                
        elif context == "url":
            # URL fragment/path injection: Handle URL encoding and JavaScript protocols
            yield url_encode(payload)
            yield url_double_encode(payload)
            url_obf = url_fragment_obfuscation(payload)
            if url_obf != payload:
                yield url_obf
            # JavaScript protocol obfuscation
            if "javascript:" in payload.lower():
                js_proto_obf = javascript_protocol_obfuscation(payload)
                if js_proto_obf != payload:
                    yield js_proto_obf
                
        elif context == "css":
            # CSS injection context: Handle CSS encoding and expression obfuscation
            yield css_escape(payload)
            yield css_hex_escape(payload)
            css_expr_obf = css_expression_obfuscation(payload)
            if css_expr_obf != payload:
                yield css_expr_obf
            
        elif context == "sql":
            # SQL injection context: Use legacy methods
            # ContextAwareSemanticMutator integration happens in InjectionEngine
            yield sql_comment_obfuscation(payload)
            yield sql_whitespace_obfuscation(payload)
            sql_kw_obf = sql_keyword_obfuscation(payload)
            if sql_kw_obf != payload:
                yield sql_kw_obf
        
        # Default param context and general obfuscations
        yield quote(payload, safe='')
        yield quote(quote(payload, safe=''), safe='')
        
        def randomize_case(text):
            return ''.join(c.upper() if random.random() > 0.5 else c.lower() for c in text)
        
        if "SELECT" in payload.upper() or "ALERT" in payload.upper() or "UNION" in payload.upper():
            yield randomize_case(payload)
            yield payload.upper()
            yield payload.lower()
            
        if " " in payload:
            yield payload.replace(" ", "/**/")
            
        def to_fullwidth(text):
            result = []
            for c in text:
                code = ord(c)
                if 33 <= code <= 126:
                    result.append(chr(code + 0xFEE0))
                else:
                    result.append(c)
            return ''.join(result)
            
        yield to_fullwidth(payload)
        
        keywords = ["SELECT", "UNION", "FROM", "WHERE", "AND", "OR", "INSERT", "UPDATE", "DELETE", "DROP", "alert", "script"]
        for keyword in keywords:
            if keyword in payload.upper():
                yield payload.replace(keyword, keyword[0] + "%09" + keyword[1:])
                yield payload.replace(keyword, keyword[0] + "%0a" + keyword[1:])
                break
        
        def json_unicode_escape(text):
            result = []
            for c in text:
                if c == "'":
                    result.append("\\u0027")
                elif c == '"':
                    result.append("\\u0022")
                elif ord(c) < 32 or ord(c) > 126:
                    result.append(f"\\u{ord(c):04x}")
                else:
                    result.append(c)
            return ''.join(result)
        
        html_entity = ''.join(f"&#{ord(c)};" for c in payload)
        yield html_entity
        
        unicode_escaped = ''.join(f"\\u{ord(c):04x}" for c in payload)
        yield unicode_escaped
        
        yield quote(quote(quote(payload, safe=''), safe=''))
        yield payload.replace(" ", " %00")
        
        if " " in payload:
            comment_variant = payload.replace(" ", "/**/")
            yield quote(comment_variant, safe='')
            yield quote(quote(comment_variant, safe=''), safe='')
            
        if "SELECT" in payload.upper() and " " in payload:
            mixed_case = randomize_case(payload)
            yield mixed_case.replace(" ", "/**/")
            
        if "SELECT" in payload.upper():
            fullwidth = to_fullwidth(payload)
            for keyword in keywords:
                if keyword in payload.upper():
                    yield fullwidth.replace(keyword.upper(), keyword.upper()[0] + "%09" + keyword.upper()[1:])
                    break
    
    variants = list(set(generate_variants()))
    _obfuscation_cache[cache_key] = variants
    return variants

# Context-specific obfuscation functions
def json_escape(payload):
    """JSON string escaping with proper quote handling."""
    escaped = payload.replace('\\', '\\\\').replace('"', '\\"')
    return f'"{escaped}"'

def json_unicode_escape(payload):
    """Unicode escape for JSON context."""
    result = []
    for c in payload:
        if c == "'":
            result.append("\\u0027")
        elif c == '"':
            result.append("\\u0022")
        elif c == '\\':
            result.append("\\u005C")
        elif ord(c) < 32 or ord(c) > 126:
            result.append(f"\\u{ord(c):04x}")
        else:
            result.append(c)
    return ''.join(result)

def json_html_escape(payload):
    """Combined JSON and HTML entity escaping for JSON-in-HTML context."""
    # First JSON escape, then HTML entity encode
    json_escaped = json_escape(payload)
    html_escaped = json_escaped.replace('"', '&quot;').replace("'", '&#39;')
    return html_escaped

def json_property_obfuscation(payload):
    """Obfuscate JSON property names and structure."""
    if '=' in payload:
        key, value = payload.split('=', 1)
        # Obfuscate key with various techniques
        obfuscated_keys = [
            f'"{key}"',
            f"'{key}'",
            f'\\u{ord(key[0]):04x}{key[1:]}',
            key,
            f' {key} ',
            f'/*comment*/{key}/*comment*/'
        ]
        # Return first variant as string
        return f'{obfuscated_keys[0]}={value}'
    return payload

def html_entity_encode(payload):
    """HTML entity encoding."""
    return ''.join(f'&#{ord(c)};' for c in payload)

def html_hex_encode(payload):
    """HTML hexadecimal entity encoding."""
    return ''.join(f'&#x{ord(c):x};' for c in payload)

def html_decimal_encode(payload):
    """HTML decimal encoding with mixed case."""
    return ''.join(f'&#{ord(c)};' if random.random() > 0.5 else f'&#x{ord(c):x};' for c in payload)

def script_tag_obfuscation(payload):
    """Script tag obfuscation techniques."""
    obfuscated = payload.lower()
    # Replace script tag variations
    obfuscated = obfuscated.replace('<script', '<scr\0ipt')
    obfuscated = obfuscated.replace('<script', '<scr<!-- -->ipt')
    obfuscated = obfuscated.replace('<script', '<script/x')
    # Replace alert variations
    obfuscated = obfuscated.replace('alert(', 'window[\'alert\'](')
    obfuscated = obfuscated.replace('alert(', 'window["alert"](')
    obfuscated = obfuscated.replace('alert(', '\\u0061\\u006c\\u0065\\u0072\\u0074(')
    return obfuscated

def js_string_escape(payload):
    """JavaScript string escaping."""
    escaped = payload.replace('\\', '\\\\').replace("'", "\\'").replace('"', '\\"')
    return f"'{escaped}'"

def js_unicode_escape(payload):
    """JavaScript unicode escaping."""
    return ''.join(f'\\u{ord(c):04x}' for c in payload)

def js_backtick_escape(payload):
    """JavaScript template literal escaping."""
    escaped = payload.replace('`', '\\`').replace('${', '\\${')
    return f'`{escaped}`'

def js_code_obfuscation(payload):
    """JavaScript code obfuscation."""
    obfuscated = payload
    # Replace common JavaScript patterns
    obfuscated = obfuscated.replace('document.', 'window[\'document\'].')
    obfuscated = obfuscated.replace('document.', 'window["document"].')
    obfuscated = obfuscated.replace('window.', 'self[\'window\'].')
    obfuscated = obfuscated.replace('location.', 'window[\'location\'].')
    obfuscated = obfuscated.replace('alert(', 'window[\\\'alert\\\'](')
    # Access property obfuscation
    obfuscated = obfuscated.replace('.cookie', '[\\\'cookie\\\']')
    obfuscated = obfuscated.replace('.location', '[\\\'location\\\']')
    return obfuscated

def url_encode(payload):
    """URL encoding."""
    return quote(payload, safe='')

def url_double_encode(payload):
    """Double URL encoding."""
    return quote(quote(payload, safe=''), safe='')

def url_fragment_obfuscation(payload):
    """URL fragment obfuscation."""
    # Encode for URL fragment context
    encoded = quote(payload, safe='!#$&\'()*+,/:;=?@[]~')
    # Return first variant
    return encoded

def javascript_protocol_obfuscation(payload):
    """JavaScript protocol obfuscation for URL context."""
    obfuscated = payload.lower()
    # JavaScript protocol variations - use first one
    if 'javascript:' in obfuscated:
        return obfuscated.replace('javascript:', 'javascript\\u003a')
    return payload

def css_escape(payload):
    """CSS escaping."""
    escaped = payload.replace('\\', '\\\\').replace('"', '\\"').replace("'", "\\'")
    return f'"{escaped}"'

def css_hex_escape(payload):
    """CSS hexadecimal escaping."""
    return ''.join(f'\\{ord(c):x} ' if ord(c) > 127 else c for c in payload)

def css_expression_obfuscation(payload):
    """CSS expression obfuscation."""
    obfuscated = payload.lower()
    # CSS expression variations
    obfuscated = obfuscated.replace('expression(', 'exp/*comment*/ression(')
    obfuscated = obfuscated.replace('expression(', 'e\\xpression(')
    obfuscated = obfuscated.replace('expression(', 'e\\78 xpression(')
    return obfuscated

class ContextAwareSemanticMutator:
    """
    Context-Aware Semantic Mutator for advanced payload obfuscation.
    
    Instead of random character insertion, mutates based on:
    - Backend language (MySQL, PostgreSQL, SQL Server, Oracle, SQLite)
    - Detected WAF/CDN signatures
    - Semantic context of the injection point
    - Grammar-based transformations rather than static string replacement
    """
    
    def __init__(self):
        print("ContextAwareSemanticMutator.__init__ started")
        self.database_cache = {}
        self.waf_evasion_fallbacks = []
        print("Initializing grammar templates...")
        self.grammar_templates = self._init_grammar_templates()
        print("Initializing SQL grammar...")
        self.sql_grammar = self._init_sql_grammar()
        print("Initializing default WAF fallbacks...")
        self.init_default_waf_fallbacks()
        print("ContextAwareSemanticMutator.__init__ completed")
        
    def _init_sql_grammar(self):
        """
        Initialize SQL grammar for AST-based payload generation.
        
        This defines the structure of SQL statements for intelligent mutation.
        """
        return {
            'statement_types': ['SELECT', 'INSERT', 'UPDATE', 'DELETE', 'UNION'],
            'clauses': {
                'SELECT': ['FROM', 'WHERE', 'GROUP BY', 'HAVING', 'ORDER BY', 'LIMIT'],
                'INSERT': ['INTO', 'VALUES', 'SET'],
                'UPDATE': ['SET', 'WHERE'],
                'DELETE': ['FROM', 'WHERE'],
                'UNION': ['SELECT', 'FROM', 'WHERE']
            },
            'operators': ['=', '!=', '<>', '>', '<', '>=', '<=', 'LIKE', 'IN', 'BETWEEN', 'IS', 'AND', 'OR', 'NOT'],
            'functions': {
                'mysql': ['COUNT', 'SUM', 'AVG', 'MIN', 'MAX', 'CONCAT', 'SUBSTRING', 'LENGTH', 'USER', 'VERSION', 'DATABASE'],
                'postgresql': ['COUNT', 'SUM', 'AVG', 'MIN', 'MAX', 'CONCAT', 'SUBSTRING', 'LENGTH', 'CURRENT_USER', 'VERSION', 'CURRENT_DATABASE'],
                'sqlserver': ['COUNT', 'SUM', 'AVG', 'MIN', 'MAX', 'CONCAT', 'SUBSTRING', 'LEN', 'USER_NAME', 'VERSION', 'DB_NAME'],
                'oracle': ['COUNT', 'SUM', 'AVG', 'MIN', 'MAX', 'CONCAT', 'SUBSTR', 'LENGTH', 'USER', 'VERSION', 'SYS_CONTEXT'],
                'sqlite': ['COUNT', 'SUM', 'AVG', 'MIN', 'MAX', 'SUBSTR', 'LENGTH']
            },
            'data_types': ['INT', 'VARCHAR', 'TEXT', 'DATE', 'DATETIME', 'BOOLEAN'],
            'keywords': ['SELECT', 'FROM', 'WHERE', 'AND', 'OR', 'UNION', 'ALL', 'DISTINCT', 'ORDER', 'BY', 'GROUP', 'HAVING', 'LIMIT', 'OFFSET']
        }
    
    def _init_grammar_templates(self):
        """Initialize grammar-based fuzzing templates for SQL injection."""
        return {
            'mysql': {
                'conditional_comment': lambda x: f"/*!50000{x}*/",
                'version_comment': lambda x: f"/*!{x}*/",
                'inline_comment': lambda x: f"{x}--",
                'block_comment': lambda x: f"/*{x}*/",
                'hex_encoding': lambda x: "0x" + x.encode('utf-8').hex(),
                'char_encoding': lambda x: "".join(f"CHAR({ord(c)})" for c in x),
                'whitespace': [' ', '/**/', '%09', '%0a', '%0b', '%0c', '%0d', '%a0', '/*comment*/'],
                'case_mixed': lambda x: ''.join(c.upper() if i % 2 == 0 else c.lower() for i, c in enumerate(x)),
                'case_random': lambda x: ''.join(c.upper() if random.random() > 0.5 else c.lower() for c in x),
            },
            'postgresql': {
                'comment': lambda x: f"{x}--",
                'block_comment': lambda x: f"/*{x}*/",
                'dollar_quoting': lambda x: f"$${x}$$",
                'escape_string': lambda x: x.replace("'", "''"),
                'whitespace': [' ', '%20', '%09', '%0a', '%0c', '%0d'],
                'case_mixed': lambda x: ''.join(c.upper() if i % 2 == 0 else c.lower() for i, c in enumerate(x)),
            },
            'sqlserver': {
                'comment': lambda x: f"{x}--",
                'block_comment': lambda x: f"/*{x}*/",
                'square_brackets': lambda x: f"[{x}]",
                'exec': lambda x: f"EXEC('{x}')",
                'whitespace': [' ', '%20', '%09', '%0a', '%0c', '%0d'],
                'case_insensitive': lambda x: x.upper(),
            },
            'oracle': {
                'comment': lambda x: f"{x}--",
                'block_comment': lambda x: f"/*{x}*/",
                'concat': lambda x: f"'{x}'",
                'whitespace': [' ', '%20', '%09', '%0a', '%0c', '%0d'],
                'case_insensitive': lambda x: x.upper(),
            },
            'sqlite': {
                'comment': lambda x: f"{x}--",
                'block_comment': lambda x: f"/*{x}*/",
                'attach': lambda x: f"ATTACH DATABASE '{x}' AS temp",
                'whitespace': [' ', '%20', '%09', '%0a', '%0c', '%0d'],
            }
        }
    
    def detect_database(self, headers=None, html_content=None, error_messages=None):
        """
        Detect the database backend from various sources.
        
        Returns: Database type ('mysql', 'postgresql', 'sqlserver', 'oracle', 'sqlite', 'unknown')
        """
        cache_key = (str(headers), str(html_content)[:500] if html_content else None, str(error_messages)[:500] if error_messages else None)
        if cache_key in self.database_cache:
            return self.database_cache[cache_key]
        
        db_type = 'unknown'
        
        # Detection from headers
        if headers:
            headers_dict = dict(headers) if not isinstance(headers, dict) else headers
            server_header = headers_dict.get('Server', '').lower()
            
            if 'mysql' in server_header:
                db_type = 'mysql'
            elif 'postgresql' in server_header or 'postgres' in server_header:
                db_type = 'postgresql'
            elif 'microsoft' in server_header or 'sql server' in server_header:
                db_type = 'sqlserver'
            elif 'oracle' in server_header:
                db_type = 'oracle'
            elif 'sqlite' in server_header:
                db_type = 'sqlite'
        
        # Detection from HTML content
        if html_content and db_type == 'unknown':
            html_lower = html_content.lower()
            
            if 'mysql' in html_lower or 'mysqli' in html_lower:
                db_type = 'mysql'
            elif 'postgresql' in html_lower or 'postgres' in html_lower or 'psql' in html_lower:
                db_type = 'postgresql'
            elif 'sql server' in html_lower or 'mssql' in html_lower or 'tds' in html_lower:
                db_type = 'sqlserver'
            elif 'oracle' in html_lower or 'ora-' in html_lower:
                db_type = 'oracle'
            elif 'sqlite' in html_lower:
                db_type = 'sqlite'
        
        # Detection from error messages
        if error_messages and db_type == 'unknown':
            error_lower = error_messages.lower()
            
            # MySQL error patterns
            if any(pattern in error_lower for pattern in ['mysql', 'mysqli', 'you have an error in your sql syntax', 'warning: mysql']):
                db_type = 'mysql'
            # PostgreSQL error patterns
            elif any(pattern in error_lower for pattern in ['postgresql', 'postgres', 'pg_query', 'psql', 'fatal error']):
                db_type = 'postgresql'
            # SQL Server error patterns
            elif any(pattern in error_lower for pattern in ['sql server', 'microsoft sql', 'mssql', 'odbc sql server', 'unclosed quotation mark']):
                db_type = 'sqlserver'
            # Oracle error patterns
            elif any(pattern in error_lower for pattern in ['oracle', 'ora-', 'pls-', 'tns-', 'oracle database']):
                db_type = 'oracle'
            # SQLite error patterns
            elif any(pattern in error_lower for pattern in ['sqlite', 'sqlite3', 'sqlite_error']):
                db_type = 'sqlite'
        
        self.database_cache[cache_key] = db_type
        return db_type
    
    def mutate_sql_payload(self, payload, db_type='mysql', waf_type='generic'):
        """
        Mutate SQL payload based on database type and WAF detection.
        
        Uses grammar-based transformations rather than static string replacement.
        """
        if db_type not in self.grammar_templates:
            db_type = 'mysql'  # Default to MySQL if unknown
        
        templates = self.grammar_templates[db_type]
        variants = []
        
        # Grammar-based transformations
        if 'conditional_comment' in templates and db_type == 'mysql':
            # MySQL-specific conditional comments
            keywords = ['SELECT', 'UNION', 'FROM', 'WHERE', 'AND', 'OR']
            for keyword in keywords:
                if keyword.lower() in payload.lower():
                    mutated = payload.lower().replace(keyword.lower(), templates['conditional_comment'](keyword))
                    variants.append(mutated)
        
        if 'version_comment' in templates and db_type == 'mysql':
            # MySQL version-specific comments
            keywords = ['SELECT', 'UNION', 'FROM', 'WHERE']
            for keyword in keywords:
                if keyword.lower() in payload.lower():
                    mutated = payload.lower().replace(keyword.lower(), templates['version_comment'](keyword))
                    variants.append(mutated)
        
        if 'hex_encoding' in templates:
            # Hex encoding for string literals
            if "'" in payload or '"' in payload:
                # Extract string literals and encode them
                import re
                strings = re.findall(r"['\"]([^'\"]*)['\"]", payload)
                for s in strings:
                    if len(s) > 2:  # Only encode longer strings
                        hex_encoded = templates['hex_encoding'](s)
                        mutated = payload.replace(f"'{s}'", hex_encoded).replace(f'"{s}"', hex_encoded)
                        variants.append(mutated)
        
        if 'char_encoding' in templates and db_type == 'mysql':
            # CHAR encoding for MySQL
            if "'" in payload or '"' in payload:
                import re
                strings = re.findall(r"['\"]([^'\"]*)['\"]", payload)
                for s in strings:
                    if len(s) > 1 and len(s) < 10:  # Only encode short strings
                        char_encoded = templates['char_encoding'](s)
                        mutated = payload.replace(f"'{s}'", char_encoded).replace(f'"{s}"', char_encoded)
                        variants.append(mutated)
        
        if 'dollar_quoting' in templates and db_type == 'postgresql':
            # PostgreSQL dollar quoting
            if "'" in payload:
                mutated = payload.replace("'", "$$")
                variants.append(mutated)
        
        if 'square_brackets' in templates and db_type == 'sqlserver':
            # SQL Server square brackets for identifiers
            keywords = ['SELECT', 'FROM', 'WHERE', 'INSERT', 'UPDATE', 'DELETE']
            for keyword in keywords:
                if keyword.lower() in payload.lower():
                    mutated = payload.lower().replace(keyword.lower(), templates['square_brackets'](keyword.lower()))
                    variants.append(mutated)
        
        # Advanced whitespace obfuscation based on WAF
        waf_specific_whitespace = self._get_waf_specific_whitespace(waf_type, db_type)
        for ws in waf_specific_whitespace:
            mutated = payload.replace(' ', ws)
            variants.append(mutated)
        
        # Case transformations
        if 'case_mixed' in templates:
            keywords = ['SELECT', 'UNION', 'FROM', 'WHERE', 'AND', 'OR', 'INSERT', 'UPDATE', 'DELETE']
            for keyword in keywords:
                if keyword.lower() in payload.lower():
                    mixed_case = templates['case_mixed'](keyword)
                    mutated = payload.lower().replace(keyword.lower(), mixed_case)
                    variants.append(mutated)
        
        if 'case_random' in templates:
            keywords = ['SELECT', 'UNION', 'FROM', 'WHERE', 'AND', 'OR']
            for keyword in keywords:
                if keyword.lower() in payload.lower():
                    random_case = templates['case_random'](keyword)
                    mutated = payload.lower().replace(keyword.lower(), random_case)
                    variants.append(mutated)
        
        # Ensure original payload is included
        variants.append(payload)
        
        # If no variants were generated, try WAF evasion fallbacks
        if len(variants) <= 1:
            context = {'db_type': db_type, 'waf_type': waf_type}
            fallback_variants = self.try_waf_evasion_fallbacks(payload, context)
            variants.extend(fallback_variants)
        
        # Remove duplicates and return
        return list(set(variants))
    
    def _get_waf_specific_whitespace(self, waf_type, db_type):
        """
        Get WAF-specific whitespace obfuscation techniques.
        
        Different WAFs have different signatures for common obfuscations.
        """
        base_whitespace = ['%20', '%09', '%0a', '%0c', '%0d']
        
        waf_specific = {
            'cloudflare': {
                'mysql': ['/**/', '%09', '%0a', '%0b', '%0c', '%0d', '%a0', '/*!50000 */'],
                'postgresql': ['/**/', '%09', '%0a', '%0c', '%0d'],
                'sqlserver': ['/**/', '%09', '%0a', '%0c', '%0d'],
                'oracle': ['/**/', '%09', '%0a', '%0c', '%0d'],
            },
            'aws-waf': {
                'mysql': ['/**/', '%09', '%0a', '%0b', '%0c', '%0d', '%a0'],
                'postgresql': ['/**/', '%09', '%0a', '%0c', '%0d'],
                'sqlserver': ['/**/', '%09', '%0a', '%0c', '%0d'],
            },
            'sucuri': {
                'mysql': ['/**/', '%09', '%0a', '%0c', '%0d'],
                'postgresql': ['/**/', '%09', '%0a', '%0c', '%0d'],
            },
            'generic': {
                'mysql': ['/**/', '%09', '%0a', '%0b', '%0c', '%0d', '%a0'],
                'postgresql': ['/**/', '%09', '%0a', '%0c', '%0d'],
                'sqlserver': ['/**/', '%09', '%0a', '%0c', '%0d'],
                'oracle': ['/**/', '%09', '%0a', '%0c', '%0d'],
            }
        }
        
        if waf_type in waf_specific and db_type in waf_specific[waf_type]:
            return waf_specific[waf_type][db_type]
        elif db_type in waf_specific['generic']:
            return waf_specific['generic'][db_type]
        else:
            return base_whitespace
    
    def register_waf_evasion_fallback(self, fallback_method):
        """
        Register a WAF evasion fallback method.
        
        When primary obfuscation techniques fail, these fallbacks are tried.
        """
        self.waf_evasion_fallbacks.append(fallback_method)
    
    def try_waf_evasion_fallbacks(self, payload, context):
        """
        Try registered WAF evasion fallback methods.
        
        Returns: List of payloads generated by fallback methods
        """
        fallback_payloads = []
        for fallback in self.waf_evasion_fallbacks:
            try:
                result = fallback(payload, context)
                if result:
                    fallback_payloads.extend(result if isinstance(result, list) else [result])
            except Exception as e:
                logging.debug(f"WAF evasion fallback error: {e}")
        
        return fallback_payloads
    
    def init_default_waf_fallbacks(self):
        """
        Initialize default WAF evasion fallback methods.
        
        These are tried when primary obfuscation techniques are detected/blocked.
        """
        # Fallback 1: Encoding chain fallback
        def encoding_chain_fallback(payload, context):
            """Try multiple encoding techniques in sequence."""
            import base64
            import urllib.parse
            
            variants = []
            
            # Base64 encoding
            try:
                b64_encoded = base64.b64encode(payload.encode()).decode()
                variants.append(b64_encoded)
            except:
                pass
            
            # URL encoding chain
            try:
                url_encoded = urllib.parse.quote(payload)
                double_encoded = urllib.parse.quote(url_encoded)
                variants.append(double_encoded)
            except:
                pass
            
            # Hex encoding
            try:
                hex_encoded = payload.encode('utf-8').hex()
                variants.append(hex_encoded)
            except:
                pass
            
            return variants
        
        # Fallback 2: Fragmentation fallback
        def fragmentation_fallback(payload, context):
            """Split payload into fragments to avoid signature detection."""
            if len(payload) < 10:
                # For very short payloads, use character-level obfuscation instead
                variants = []
                # Character-level encoding
                for i, char in enumerate(payload):
                    if char.isalnum():
                        # URL encode individual characters
                        variants.append(payload[:i] + '%' + hex(ord(char))[2:].upper() + payload[i+1:])
                
                # If no alphanumeric characters, use other techniques
                if not variants:
                    variants.append(payload.replace(' ', '/**/'))
                    variants.append(payload.replace(' ', '%20'))
                
                return variants
            
            variants = []
            mid_point = len(payload) // 2
            
            # Split with comment insertion
            variants.append(payload[:mid_point] + '/**/' + payload[mid_point:])
            variants.append(payload[:mid_point] + '--' + payload[mid_point:])
            variants.append(payload[:mid_point] + '%00' + payload[mid_point:])
            
            # Additional fragmentation techniques
            # Split into multiple fragments
            if len(payload) > 20:
                third_point = len(payload) // 3
                two_thirds_point = 2 * len(payload) // 3
                variants.append(payload[:third_point] + '/**/' + payload[third_point:two_thirds_point] + '/**/' + payload[two_thirds_point:])
            
            # Character-level fragmentation for sensitive keywords
            sensitive_keywords = ['script', 'alert', 'document', 'window', 'union', 'select', 'drop']
            for keyword in sensitive_keywords:
                if keyword.lower() in payload.lower():
                    # Fragment the keyword
                    start = payload.lower().find(keyword.lower())
                    if start != -1:
                        end = start + len(keyword)
                        fragmented = payload[:start] + '/**/' + payload[start:end] + '/**/' + payload[end:]
                        variants.append(fragmented)
            
            return variants
        
        # Fallback 3: Case transformation fallback
        def case_transformation_fallback(payload, context):
            """Advanced case transformations."""
            variants = []
            
            # Random case
            import random
            random_case = ''.join(c.upper() if random.random() > 0.5 else c.lower() for c in payload)
            variants.append(random_case)
            
            # Alternating case
            alt_case = ''.join(c.upper() if i % 2 == 0 else c.lower() for i, c in enumerate(payload))
            variants.append(alt_case)
            
            # Vowel case
            vowel_case = ''.join(c.upper() if c.lower() in 'aeiou' else c.lower() for c in payload)
            variants.append(vowel_case)
            
            return variants
        
        # Fallback 4: Unicode transformation fallback
        def unicode_transformation_fallback(payload, context):
            """Unicode encoding transformations."""
            variants = []
            
            # Unicode escape
            unicode_escaped = ''.join(f'\\u{ord(c):04x}' for c in payload)
            variants.append(unicode_escaped)
            
            # Fullwidth characters (for certain contexts)
            fullwidth = ''.join(chr(ord(c) + 0xFEE0) if ord(c) < 128 else c for c in payload)
            variants.append(fullwidth)
            
            # Homoglyph attacks
            homoglyphs = {
                'a': 'а', 'e': 'е', 'o': 'о', 'p': 'р', 's': 'ѕ',
                'c': 'с', 'i': 'і', 'l': 'ӏ', 'n': 'п', 'v': 'ѵ'
            }
            homoglyph_payload = ''.join(homoglyphs.get(c.lower(), c) for c in payload)
            variants.append(homoglyph_payload)
            
            return variants
        
        # Fallback 5: Protocol-specific fallback
        def protocol_specific_fallback(payload, context):
            """Protocol-specific encoding based on context."""
            variants = []
            
            if context.get('protocol') == 'http':
                # HTTP-specific techniques
                variants.append(payload.replace(' ', '+'))
                variants.append(payload.replace(' ', '%20'))
            
            if context.get('content_type') == 'application/json':
                # JSON-specific techniques
                import json
                try:
                    json_obj = {"payload": payload}
                    json_str = json.dumps(json_obj)
                    variants.append(json_str)
                except:
                    pass
            
            if context.get('content_type') == 'application/xml':
                # XML-specific techniques
                xml_payload = f"<![CDATA[{payload}]]>"
                variants.append(xml_payload)
            
            return variants
        
        # Register all fallbacks
        self.register_waf_evasion_fallback(encoding_chain_fallback)
        self.register_waf_evasion_fallback(fragmentation_fallback)
        self.register_waf_evasion_fallback(case_transformation_fallback)
        self.register_waf_evasion_fallback(unicode_transformation_fallback)
        self.register_waf_evasion_fallback(protocol_specific_fallback)
    
    def generate_grammar_based_payloads(self, base_payload, db_type='mysql', max_variants=10):
        """
        Generate payloads using grammar-based AST transformations.
        
        This is more sophisticated than simple string replacement - it understands
        SQL structure and mutates while maintaining syntactic validity.
        """
        grammar = self.sql_grammar
        variants = []
        
        # Parse the base payload to understand its structure
        payload_structure = self._parse_sql_structure(base_payload)
        
        # Generate variants based on grammar rules
        for _ in range(max_variants):
            variant = self._mutate_sql_ast(base_payload, payload_structure, grammar, db_type)
            if variant and variant != base_payload:
                variants.append(variant)
        
        return variants
    
    def _parse_sql_structure(self, payload):
        """
        Parse SQL payload to identify its structure.
        
        Returns a dict with identified statement types, clauses, and operators.
        """
        structure = {
            'statement_type': None,
            'clauses': [],
            'operators': [],
            'functions': [],
            'keywords': []
        }
        
        payload_upper = payload.upper()
        
        # Identify statement type
        for stmt_type in self.sql_grammar['statement_types']:
            if stmt_type in payload_upper:
                structure['statement_type'] = stmt_type
                break
        
        # Identify clauses
        for clause_type, clause_keywords in self.sql_grammar['clauses'].items():
            for keyword in clause_keywords:
                if keyword in payload_upper:
                    structure['clauses'].append(keyword)
        
        # Identify operators
        for operator in self.sql_grammar['operators']:
            if operator in payload_upper:
                structure['operators'].append(operator)
        
        # Identify functions
        for db_func_list in self.sql_grammar['functions'].values():
            for func in db_func_list:
                if func + '(' in payload_upper:
                    structure['functions'].append(func)
        
        # Identify keywords
        for keyword in self.sql_grammar['keywords']:
            if keyword in payload_upper:
                structure['keywords'].append(keyword)
        
        return structure
    
    def _mutate_sql_ast(self, payload, structure, grammar, db_type):
        """
        Mutate SQL payload using AST-based transformations.
        
        This maintains syntactic validity while applying semantic mutations.
        """
        import random
        
        if not structure['statement_type']:
            return None
        
        mutated = payload
        mutation_type = random.choice([
            'reorder_clauses',
            'substitute_functions',
            'add_conditions',
            'change_operators',
            'inject_comments'
        ])
        
        if mutation_type == 'reorder_clauses' and len(structure['clauses']) > 1:
            # Reorder clauses using proper AST-based dependency analysis
            try:
                import sqlparse
                from sqlparse.sql import IdentifierList, Identifier, Where, Comparison, Operation
                from sqlparse.tokens import Keyword, DML, Name
                
                # Parse the SQL statement into AST
                parsed = sqlparse.parse(mutated)
                if not parsed:
                    return mutated
                
                stmt = parsed[0]
                
                # Define clause dependency rules based on SQL syntax
                # Clauses can only be reordered if they don't break dependencies
                clause_dependencies = {
                    'SELECT': [],  # No dependencies
                    'FROM': ['SELECT'],  # Requires SELECT
                    'WHERE': ['SELECT', 'FROM'],  # Requires SELECT and FROM
                    'GROUP BY': ['SELECT', 'FROM', 'WHERE'],  # Requires SELECT, FROM, WHERE
                    'HAVING': ['SELECT', 'FROM', 'WHERE', 'GROUP BY'],  # Requires all previous
                    'ORDER BY': ['SELECT', 'FROM'],  # Can come after WHERE or GROUP BY
                    'LIMIT': ['SELECT', 'FROM', 'WHERE', 'GROUP BY', 'HAVING', 'ORDER BY']  # Usually last
                }
                
                # Extract clauses with their positions and dependencies
                clause_info = []
                tokens_list = list(stmt.flatten())
                
                for i, token in enumerate(tokens_list):
                    token_upper = token.value.upper().strip()
                    if token_upper in clause_dependencies:
                        # Find the extent of this clause
                        clause_start = i
                        clause_end = len(tokens_list)
                        
                        # Find where this clause ends (next keyword clause or end)
                        for j in range(i + 1, len(tokens_list)):
                            next_token_upper = tokens_list[j].value.upper().strip()
                            if next_token_upper in clause_dependencies and next_token_upper != token_upper:
                                clause_end = j
                                break
                        
                        # Get clause content
                        clause_tokens = tokens_list[clause_start:clause_end]
                        clause_content = ''.join(t.value for t in clause_tokens)
                        
                        clause_info.append({
                            'name': token_upper,
                            'start': clause_start,
                            'end': clause_end,
                            'content': clause_content,
                            'dependencies': clause_dependencies[token_upper]
                        })
                
                # Sort clauses by their position
                clause_info.sort(key=lambda x: x['start'])
                
                # Try to find reorderable clauses (those with compatible dependencies)
                for i in range(len(clause_info) - 1):
                    current = clause_info[i]
                    next_clause = clause_info[i + 1]
                    
                    # Check if next clause can be moved before current
                    # Current's dependencies must be satisfied by clauses before next
                    can_swap = True
                    
                    # Current clause needs its dependencies to be before it
                    for dep in current['dependencies']:
                        # Check if dependency exists before the swap position
                        dep_found = False
                        for prev_clause in clause_info[:i]:
                            if prev_clause['name'] == dep:
                                dep_found = True
                                break
                        if not dep_found:
                            can_swap = False
                            break
                    
                    # Next clause needs its dependencies to be before it (after swap)
                    if can_swap:
                        for dep in next_clause['dependencies']:
                            dep_found = False
                            # After swap, next clause will be at current position
                            # Check if dependency exists before current position
                            for prev_clause in clause_info[:i]:
                                if prev_clause['name'] == dep:
                                    dep_found = True
                                    break
                            if not dep_found:
                                can_swap = False
                                break
                    
                    if can_swap:
                        # Perform the swap
                        before = mutated[:current['start']]
                        middle = mutated[next_clause['end']:current['end']]
                        after = mutated[next_clause['end']:]
                        
                        # Reconstruct with swapped clauses
                        mutated = before + next_clause['content'] + middle + current['content'] + after
                        break  # Only do one swap per mutation
                        
            except ImportError:
                # Fallback to simplified version if sqlparse not available
                # Define clause order dependencies (clauses that can be reordered)
                clause_order_rules = {
                    'SELECT': 0,
                    'FROM': 1,
                    'WHERE': 2,
                    'GROUP BY': 3,
                    'HAVING': 4,
                    'ORDER BY': 5,
                    'LIMIT': 6
                }
                
                # Get clauses that can be reordered (same level)
                reorderable_clauses = [c for c in structure['clauses'] if c in clause_order_rules]
                
                if len(reorderable_clauses) > 1:
                    # Extract clause positions and content
                    clause_positions = []
                    for clause in reorderable_clauses:
                        pos = mutated.upper().find(clause)
                        if pos != -1:
                            # Find the end of this clause (next clause or end of string)
                            clause_end = len(mutated)
                            for other_clause in reorderable_clauses:
                                if other_clause != clause:
                                    other_pos = mutated.upper().find(other_clause)
                                    if other_pos > pos:
                                        clause_end = min(clause_end, other_pos)
                            
                            clause_content = mutated[pos:clause_end]
                            clause_positions.append({
                                'name': clause,
                                'start': pos,
                                'end': clause_end,
                                'content': clause_content
                            })
                    
                    # Sort by position
                    clause_positions.sort(key=lambda x: x['start'])
                    
                    # Try swapping adjacent clauses that don't have strict dependencies
                    for i in range(len(clause_positions) - 1):
                        current = clause_positions[i]
                        next_clause = clause_positions[i + 1]
                        
                        # Check if these clauses can be swapped
                        current_order = clause_order_rules.get(current['name'], 999)
                        next_order = clause_order_rules.get(next_clause['name'], 999)
                        
                        # Only swap if they're close in order (independent clauses)
                        if abs(current_order - next_order) <= 1:
                            # Swap the clauses
                            before = mutated[:current['start']]
                            middle = mutated[next_clause['end']:current['end']]
                            after = mutated[next_clause['end']:]
                            
                            # Reconstruct with swapped clauses
                            mutated = before + next_clause['content'] + middle + current['content'] + after
                            break  # Only do one swap per mutation
        
        elif mutation_type == 'substitute_functions':
            # Substitute functions with database-specific equivalents
            if db_type in grammar['functions']:
                available_functions = grammar['functions'][db_type]
                for func in structure['functions']:
                    if func in available_functions:
                        # Find a different function with similar purpose
                        alternatives = [f for f in available_functions if f != func]
                        if alternatives:
                            replacement = random.choice(alternatives)
                            mutated = mutated.replace(func + '(', replacement + '(')
        
        elif mutation_type == 'add_conditions':
            # Add additional conditions to WHERE clauses
            if 'WHERE' in structure['clauses']:
                additional_conditions = [
                    " AND 1=1",
                    " AND 'a'='a'",
                    " OR 1=1",
                    " AND SLEEP(1)",
                    " AND BENCHMARK(1000000,MD5(1))" if db_type == 'mysql' else ""
                ]
                condition = random.choice([c for c in additional_conditions if c])
                if condition:
                    # Insert after WHERE clause
                    where_pos = mutated.upper().find('WHERE')
                    if where_pos != -1:
                        insert_pos = where_pos + 5
                        mutated = mutated[:insert_pos] + condition + mutated[insert_pos:]
        
        elif mutation_type == 'change_operators':
            # Change operators to equivalent alternatives
            operator_replacements = {
                '=': ['=', 'LIKE', 'IN'],
                '!=': ['!=', '<>', 'NOT LIKE'],
                '>': ['>', '>='],
                '<': ['<', '<='],
                'AND': ['AND', '&&'],
                'OR': ['OR', '||']
            }
            for operator in structure['operators']:
                if operator in operator_replacements:
                    alternatives = operator_replacements[operator]
                    replacement = random.choice(alternatives)
                    mutated = mutated.replace(f' {operator} ', f' {replacement} ')
        
        elif mutation_type == 'inject_comments':
            # Inject comments to break signatures
            comment_styles = ['/**/', '--', '#', '/*comment*/']
            for keyword in structure['keywords']:
                if random.random() > 0.5:
                    comment = random.choice(comment_styles)
                    mutated = mutated.replace(keyword, keyword[0] + comment + keyword[1:])
        
        return mutated

# Maintain backward compatibility with legacy functions
def sql_comment_obfuscation(payload):
    """SQL comment obfuscation (legacy - use ContextAwareSemanticMutator instead)."""
    mutator = ContextAwareSemanticMutator()
    return mutator.mutate_sql_payload(payload, 'mysql', 'generic')

def sql_whitespace_obfuscation(payload):
    """SQL whitespace obfuscation (legacy - use ContextAwareSemanticMutator instead)."""
    mutator = ContextAwareSemanticMutator()
    variants = []
    for ws in ['/**/', '%20', '%09', '%0a', '%0b', '%0c', '%0d', '%a0']:
        variants.append(payload.replace(' ', ws))
    return variants

def sql_keyword_obfuscation(payload):
    """SQL keyword obfuscation (legacy - use ContextAwareSemanticMutator instead)."""
    mutator = ContextAwareSemanticMutator()
    return mutator.mutate_sql_payload(payload, 'mysql', 'generic')

