# ---------------------------------------------------------------------
# SAFE ASYNC WAIT HELPER
# ---------------------------------------------------------------------
async def safe_async_wait(tasks, timeout=None, return_when=asyncio.ALL_COMPLETED):
    if not tasks:
        return set(), set()
    return await asyncio.wait(tasks, timeout=timeout, return_when=return_when)

